                        ]
                    ]
                    """
                }
            }

            run("MERYL_COUNT") {
                script "../../../meryl/count/main.nf"
                process {
                    """
                    input[0] = SEQTK_MERGEPE.out.reads
                    input[1] = channel.value(6)
                    """
                }
            }

        }

        when {
            params {
                genomescope2_args = ""
            }
            process {
